  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Whole Person Health$j$, $j${"readings": [{"title": "1 Corinthians 6 (King James Version)", "url": "/portal/bible/1Corinthians/6"}], "body": "Health is more than not being sick. It is the balance of the whole person. Health educators describe four parts: physical health (the body), mental and emotional health (thoughts and feelings), social health (relationships) and spiritual health (your relationship with God and your sense of purpose). 1 Corinthians 6:19 says, What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?\n\nThese parts affect one another. Poor sleep can hurt your mood, stress can cause headaches, and loneliness can weaken motivation to eat well or exercise. Wellness means making choices that keep all four parts strong. Scientists call things that raise your chance of illness risk factors and things that protect you protective factors. Healthy habits, supportive family, faith and regular checkups are protective factors.\n\nYour health is shaped by heredity (traits passed down), environment, behavior, and access to care. You cannot change your genes, but you can change many habits.\n\nWorked example: a student feels tired and irritable. Physical check: sleep and food. Mental check: worry or stress. Social check: conflict with friends. Spiritual check: time for prayer and rest. Common mistake: treating health as only exercise and diet. Look at all four parts.\n\nYour task: (1) Name and describe the four parts of health. (2) Give one risk factor and one protective factor. (3) Write one goal for each part of your own health. This course gives general education and is not medical advice. Talk with a parent and a doctor about your personal health.\n\nFlorida standards: HE.912.C.1, HE.912.B.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.7", "script": "Welcome to Health Education. I am Dr. Alex L. Jenkins Sr., and I am glad you are here. Listen, taking care of your health is part of taking care of the life God gave you.\n\nFirst, what is health? It is more than not being sick. It is the balance of the whole person. Physical health is the body. Mental and emotional health is your thoughts and feelings. Social health is your relationships. Spiritual health is your walk with God and your sense of purpose. First Corinthians 6:19 says your body is the temple of the Holy Ghost.\n\nNow watch this. These parts affect each other. Poor sleep can hurt your mood. Stress can bring headaches. Loneliness can drain your motivation. Risk factors raise your chance of illness. Protective factors, like healthy habits, supportive family and faith, guard you.\n\nYour health is shaped by heredity, environment, behavior and access to care. You cannot change your genes, but you can change many habits.\n\nYour task is to name the four parts of health, give a risk factor and a protective factor, and write one goal for each part. Remember, this course is education, not medical advice. Talk with a parent and a doctor about your own health. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Whole Person Health$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Nutrition and Physical Activity$j$, $j${"readings": [{"title": "Daniel 1 (King James Version)", "url": "/portal/bible/Daniel/1"}], "body": "The food you eat gives your body energy and the materials to grow and heal. Nutrients include carbohydrates, proteins, fats, vitamins, minerals and water. The United States uses MyPlate to show five food groups: fruits, vegetables, grains, protein foods and dairy. Half of your plate should be fruits and vegetables. Choose whole grains more often than refined grains, and limit added sugars, salt and heavily processed foods. Dietary guidelines advise that added sugars stay below ten percent of daily calories. Water is the best drink for most people.\n\nRead the Nutrition Facts label for serving size, calories, sodium and added sugars. A package that looks like one serving may hold two or three.\n\nTeens should get at least sixty minutes of moderate to vigorous physical activity every day, including activities that build muscles and bones. Activity strengthens the heart, improves mood and helps sleep. Warm up before exercise, cool down after it, drink water and stop if you feel sharp pain. Daniel chose simple food and water in Daniel 1:12 and looked healthier for it.\n\nWorked example: a lunch tray with grilled chicken, brown rice, a salad, fruit and water covers four groups. Common mistake: skipping meals, which often leads to overeating later. Plan three meals and healthy snacks.\n\nYour task: (1) List the five food groups. (2) Read a real food label and report serving size, calories and added sugars. (3) Plan one day of sixty minutes of activity.\n\nFlorida standards: HE.912.C.1, HE.912.B.7, HE.912.B.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.7, HE.912.B.6", "script": "Welcome back. Listen, the food you eat is fuel, and how you move is care for the body God gave you.\n\nNutrients are carbohydrates, proteins, fats, vitamins, minerals and water. MyPlate shows five food groups: fruits, vegetables, grains, protein foods and dairy. Fill half your plate with fruits and vegetables. Choose whole grains. Limit added sugar, salt and heavily processed foods. Water is the best drink for most people.\n\nNow watch this. Read the Nutrition Facts label. Look at serving size first, then calories, sodium and added sugars. A bottle that looks like one serving may be two or three.\n\nTeens need at least sixty minutes of moderate to vigorous activity every day. Activity strengthens the heart, lifts your mood and helps you sleep. Warm up, cool down, drink water, and stop if you feel sharp pain. In Daniel chapter one, Daniel chose simple food and water, and he looked healthier for it.\n\nDo not skip meals. That often leads to overeating later.\n\nYour task is to list the five food groups, read a real food label, and plan a day with sixty minutes of activity. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Nutrition and Physical Activity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Sleep, Hygiene and Stress$j$, $j${"readings": [{"title": "Psalm 127 (King James Version)", "url": "/portal/bible/Psalms/127"}], "body": "Teenagers need about eight to ten hours of sleep each night. During sleep the body repairs itself, the brain stores memories, and growth hormones are released. Too little sleep makes learning, mood and safety worse, and drowsy driving is dangerous. Psalm 127:2 says that God giveth his beloved sleep. To sleep better, keep a steady schedule, put screens away an hour before bed, avoid caffeine late in the day and keep your room dark and cool.\n\nPersonal hygiene prevents illness and builds confidence. Wash your hands with soap for twenty seconds before eating and after the restroom. Bathe regularly, brush your teeth twice a day, floss, wear clean clothing, and use sunscreen with SPF 30 or higher outdoors.\n\nStress is the body's response to pressure. The fight or flight response raises your heart rate and breathing. A little stress can help you perform, but long lasting stress can harm sleep, mood and health. Healthy ways to manage stress include prayer, exercise, rest, talking with a trusted person, organizing your time and breathing slowly. Unhealthy ways include substance use and hiding feelings. 1 Peter 5:7 says, Casting all your care upon him; for he careth for you.\n\nWorked example: before a big test, plan study blocks, sleep eight hours, eat breakfast and pray. Common mistake: staying up all night to study. Rest helps memory.\n\nYour task: (1) Write a bedtime plan. (2) List four hygiene habits. (3) Name three healthy ways to handle stress.\n\nFlorida standards: HE.912.C.1, HE.912.B.7, HE.912.B.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.7, HE.912.B.5", "script": "Welcome back. Listen, sleep, cleanliness and calm are three quiet habits that protect your health.\n\nTeenagers need about eight to ten hours of sleep. While you sleep the body repairs itself and your brain stores what you learned. Psalm 127:2 says God giveth his beloved sleep. Keep a steady schedule, put screens away an hour before bed, avoid late caffeine, and keep your room dark and cool.\n\nNow watch this. Hygiene prevents illness. Wash your hands with soap for twenty seconds. Brush twice a day and floss. Wear clean clothes. Use sunscreen of SPF 30 or higher outdoors.\n\nStress is the body's response to pressure. Your heart races. A little stress can help, but long lasting stress harms sleep, mood and health. Healthy ways to handle it are prayer, exercise, rest, talking to a trusted person, organizing your time and slow breathing. First Peter 5:7 says, Casting all your care upon him; for he careth for you.\n\nDo not stay up all night before a test. Rest helps memory.\n\nYour task is to write a bedtime plan, list four hygiene habits and name three healthy ways to manage stress. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Sleep, Hygiene and Stress$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Mental and Emotional Health$j$, $j${"readings": [{"title": "Psalm 34 (King James Version)", "url": "/portal/bible/Psalms/34"}], "body": "Mental and emotional health is how you think, feel and cope. Everyone feels sadness, worry and anger at times. These feelings are normal. A mental health concern is when strong feelings last for weeks, make school, friendships or sleep difficult, or cause thoughts of harming yourself. Common concerns in teens include anxiety and depression. They are health conditions, not signs of weak faith, and they can be treated. Psalm 34:18 says, The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.\n\nSkills that protect mental health: naming your feelings, praying, sleeping and exercising, spending time with supportive people, setting limits on social media, doing kind acts and asking for help early. Signs that a friend may need help include withdrawing, big changes in mood or sleep, giving away belongings, or talk about hopelessness or dying.\n\nIf you or someone you know is thinking about suicide or self harm, tell a trusted adult right away. You can call or text 988, the Suicide and Crisis Lifeline, at any time. If someone is in immediate danger, call 911. Never keep such a secret.\n\nWorked example: you notice a friend has stopped eating lunch with others and says nothing matters. Say, I care about you, then walk with your friend to a counselor, pastor or parent. Common mistake: promising to keep it secret.\n\nYour task: (1) List three healthy coping skills. (2) Write three signs a friend may need help. (3) Write what to do and who to contact. This lesson is education only and not medical advice.\n\nFlorida standards: HE.912.C.1, HE.912.B.3, HE.912.B.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.3, HE.912.B.4", "script": "Welcome back. Listen, taking care of your mind and heart is just as important as taking care of your body.\n\nMental and emotional health is how you think, feel and cope. Everyone feels sadness, worry and anger at times. That is normal. It becomes a concern when strong feelings last for weeks or make school, friendships or sleep hard. Anxiety and depression are health conditions. They are not signs of weak faith, and they can be treated. Psalm 34:18 says the LORD is nigh unto them that are of a broken heart.\n\nNow watch this. Protect your mind. Name your feelings. Pray. Sleep and exercise. Stay near supportive people. Limit social media. Ask for help early.\n\nSigns a friend may need help are withdrawing, big changes in mood or sleep, talking about hopelessness or dying.\n\nIf you or someone you know is thinking about suicide or self harm, tell a trusted adult right now. You can call or text 988, the Suicide and Crisis Lifeline, any time. In immediate danger, call 911. Never keep that kind of secret.\n\nYour task is to list three coping skills, three warning signs and what to do. This is education, not medical advice. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Mental and Emotional Health$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Wellness Foundations$j$, $j${"prompt": "Write a report of at least 250 words on wellness. Use complete sentences and label each part. Do not include private medical details about yourself or others. 3 John 2 says, Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.\n\nPart 1: Describe the four parts of health and explain how two of them affect each other.\nPart 2: Plan one day of meals using the five MyPlate food groups and explain how you will reach sixty minutes of activity.\nPart 3: Write a sleep and hygiene plan with at least four habits.\nPart 4: Explain three healthy ways to manage stress and tell what to do if you or a friend is in crisis, including 988 and 911.\nPart 5: Explain how Scripture teaches us to care for the body and mind.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 25 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Wellness Foundations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Caring for the Temple$j$, $j${"prompt": "Write a post of at least 120 words that (1) names one healthy habit you want to build, (2) explains the barrier that makes it hard, (3) describes one step and one trusted person who can help, and (4) connects your answer to 1 Corinthians 6:19 or Psalm 34:18. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it important to ask for help early when we struggle? Do not share private medical or family details."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Caring for the Temple$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Whole Person Health$j$, $j${"questions": [{"q": "Which is NOT one of the four parts of health in this lesson?", "options": ["Spiritual health", "Financial status", "Physical health", "Social health"]}, {"q": "A protective factor is something that:", "options": ["Raises your chance of illness", "Cannot be changed", "Lowers your chance of illness or harm", "Only affects the body"]}, {"q": "Heredity means:", "options": ["Traits passed down from parents", "The food you eat", "Your daily schedule", "Where you live"]}, {"q": "1 Corinthians 6:19 calls the body:", "options": ["Unimportant", "A burden", "The temple of the Holy Ghost", "A tool for money"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Whole Person Health$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,2}'::int[], array[$j$The four parts are physical, mental and emotional, social and spiritual.$j$,$j$Protective factors guard health.$j$,$j$Heredity is the passing of traits through genes.$j$,$j$Scripture teaches that the body is to be honored.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Whole Person Health$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Nutrition and Physical Activity$j$, $j${"questions": [{"q": "How many food groups does MyPlate show?", "options": ["Seven", "Five", "Ten", "Three"]}, {"q": "How much daily activity do teens need?", "options": ["At least sixty minutes", "Ten minutes", "One hour per week", "Only on weekends"]}, {"q": "On a food label, check this first:", "options": ["The barcode", "Serving size", "The brand logo", "The color"]}, {"q": "The best drink for most people is:", "options": ["Water", "Energy drinks", "Soda", "Sweet tea"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Nutrition and Physical Activity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,0}'::int[], array[$j$They are fruits, vegetables, grains, protein foods and dairy.$j$,$j$Teens need at least sixty minutes of moderate to vigorous activity daily.$j$,$j$Serving size tells you what the other numbers mean.$j$,$j$Water supports the body without added sugar.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Nutrition and Physical Activity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Sleep, Hygiene and Stress$j$, $j${"questions": [{"q": "How much sleep do teenagers need each night?", "options": ["About eight to ten hours", "Four hours", "Twelve to fourteen hours", "Six hours exactly"]}, {"q": "How long should you wash your hands with soap?", "options": ["One minute exactly", "Until the water is warm", "Two seconds", "Twenty seconds"]}, {"q": "A healthy way to manage stress is:", "options": ["Using substances", "Hiding feelings", "Prayer, exercise and talking with a trusted person", "Skipping sleep"]}, {"q": "The fight or flight response:", "options": ["Never helps", "Raises heart rate and breathing", "Lowers all body functions", "Only happens in sleep"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Sleep, Hygiene and Stress$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,1}'::int[], array[$j$Teens need about eight to ten hours.$j$,$j$Twenty seconds removes germs well.$j$,$j$Healthy coping supports body and mind.$j$,$j$It prepares the body to respond to pressure.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Sleep, Hygiene and Stress$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Mental and Emotional Health$j$, $j${"questions": [{"q": "You can call or text this number for the Suicide and Crisis Lifeline:", "options": ["988", "411", "311", "611"]}, {"q": "If a friend talks about wanting to die, you should:", "options": ["Post about it online", "Keep it a secret", "Ignore it", "Tell a trusted adult right away"]}, {"q": "Anxiety and depression are:", "options": ["Never serious", "Proof of weak faith", "Health conditions that can be treated", "Contagious"]}, {"q": "For immediate danger, call:", "options": ["Your school office only", "A friend", "No one", "911"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Mental and Emotional Health$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,3}'::int[], array[$j$988 is the Suicide and Crisis Lifeline.$j$,$j$Safety comes before secrecy.$j$,$j$They are treatable health conditions.$j$,$j$Emergencies require 911.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Mental and Emotional Health$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Wellness Foundations$j$, $j${"questions": [{"q": "Health includes:", "options": ["Only exercise", "Only checkups", "Physical, mental and emotional, social and spiritual parts", "Only diet"]}, {"q": "Half of your plate should be:", "options": ["Fried foods", "Desserts", "Fruits and vegetables", "Sweet drinks"]}, {"q": "Teens should be active at least:", "options": ["Never", "Sixty minutes a day", "One day a week", "Five minutes a day"]}, {"q": "A good way to sleep better is to:", "options": ["Drink caffeine at night", "Keep a steady schedule and avoid screens before bed", "Stay up late", "Sleep with a bright light"]}, {"q": "Sunscreen should be at least:", "options": ["None needed", "SPF 30", "SPF 2", "SPF 5"]}, {"q": "Healthy stress management includes:", "options": ["Prayer, exercise and talking with a trusted person", "Skipping meals", "Using drugs", "Hiding feelings"]}, {"q": "If someone may harm themselves, you should:", "options": ["Wait a week", "Joke about it", "Tell a trusted adult and call or text 988 or call 911 in danger", "Keep a secret"]}, {"q": "Mental health conditions such as anxiety:", "options": ["Show weak faith", "Are treatable health conditions", "Are rare", "Cannot be helped"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Wellness Foundations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,1,1,0,2,1}'::int[], array[$j$Health involves the whole person.$j$,$j$MyPlate suggests half fruits and vegetables.$j$,$j$Daily activity builds strength and mood.$j$,$j$Habits support rest.$j$,$j$SPF 30 or higher is recommended outdoors.$j$,$j$These coping skills build resilience.$j$,$j$Get help right away.$j$,$j$Help works, and asking early matters.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Wellness Foundations$j$ on conflict (item_id) do nothing;
